import{_ as e,o as s,c as a,a2 as i}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Config Values in Plain Language","description":"","frontmatter":{},"headers":[],"relativePath":"openshield-xdp/user-guide/config-values.md","filePath":"openshield-xdp/user-guide/config-values.md","lastUpdated":1785906636000}'),d={name:"openshield-xdp/user-guide/config-values.md"};function o(n,t,r,l,c,h){return s(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="config-values-in-plain-language" tabindex="-1">Config Values in Plain Language <a class="header-anchor" href="#config-values-in-plain-language" aria-label="Permalink to &quot;Config Values in Plain Language&quot;">​</a></h1><p>Everything lives in <code>/etc/openshield/openshield.yaml</code>. After editing, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reload</span></span></code></pre></div><p>Most values apply instantly (&quot;runtime-safe&quot;). A few — marked 🔒 in the <a href="/pingless-studios-docs/openshield-xdp/configuration/reference">full reference</a> — need <code>sudo openshield unload &amp;&amp; sudo openshield load</code>.</p><p>You almost never need to edit most of this file. The preset you picked at install time already tuned the numbers. This page explains what each group does so you can make <strong>one informed change</strong> instead of guessing.</p><h2 id="rate-limits-static-threshold" tabindex="-1">Rate limits (<code>static.*_threshold</code>) <a class="header-anchor" href="#rate-limits-static-threshold" aria-label="Permalink to &quot;Rate limits (`static.*_threshold`)&quot;">​</a></h2><p>How much traffic a single IP may send before it starts gaining suspicion points. Defaults shown are the code defaults — your preset likely set different values.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Plain meaning</th><th>When to touch it</th></tr></thead><tbody><tr><td><code>pps_threshold</code></td><td>850</td><td>Total packets/s one IP may send</td><td>Almost never — presets cover this</td></tr><tr><td><code>bps_threshold</code></td><td>8,912,896</td><td>Bytes/s one IP may send (~8.5 MB/s)</td><td>Raise if legit single clients download faster than this</td></tr><tr><td><code>tcp_pps_threshold</code></td><td>680</td><td>TCP packets/s per IP</td><td>Rarely</td></tr><tr><td><code>udp_pps_threshold</code></td><td>425</td><td>UDP packets/s per IP</td><td>Raise slightly for UDP-heavy services (voice, some games)</td></tr><tr><td><code>icmp_pps_threshold</code></td><td>85</td><td>Ping packets/s per IP</td><td>Rarely — 85/s is already generous</td></tr><tr><td><code>syn_pps_threshold</code></td><td>170</td><td>New TCP connections/s per IP</td><td>Raise for legit high-connection services (busy APIs, proxies)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Legit TCP clients are exempt</p><p>Since v2.0.0, an IP that completed a real TCP connection is exempt from <code>pps_threshold</code>, <code>bps_threshold</code>, and <code>tcp_pps_threshold</code> scoring (see <code>ct_established_exempt</code> below). These limits mostly matter for unproven sources now.</p></div><h2 id="scoring-static-score-suspicion" tabindex="-1">Scoring (<code>static.*_score</code>, <code>suspicion_*</code>) <a class="header-anchor" href="#scoring-static-score-suspicion" aria-label="Permalink to &quot;Scoring (`static.*_score`, `suspicion_*`)&quot;">​</a></h2><p>When a limit above is exceeded, the IP gains points. At <code>suspicion_threshold</code> (default <strong>100</strong>) it&#39;s banned for <code>ban_duration</code> seconds (default <strong>3600</strong> = 1 hour).</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Plain meaning</th></tr></thead><tbody><tr><td><code>pps_score</code> / <code>bps_score</code></td><td>20</td><td>Points per second spent over the PPS/BPS limit</td></tr><tr><td><code>tcp_pps_score</code> / <code>udp_pps_score</code></td><td>15</td><td>Points for TCP/UDP limit violations</td></tr><tr><td><code>icmp_pps_score</code></td><td>25</td><td>Points for ICMP violations</td></tr><tr><td><code>syn_pps_score</code></td><td>30</td><td>Points for SYN violations (floods are taken more seriously)</td></tr><tr><td><code>suspicion_decay</code></td><td>0.5</td><td>How much of the score is kept each second (0.5 = half fades away)</td></tr></tbody></table><p><strong>When to touch:</strong> basically never by hand. If bans feel too slow or too eager, rerun <code>sudo openshield reconfigure</code> and pick a stricter or more relaxed preset instead — presets tune all scores together so they stay coherent. (v2.1.1 retuned preset scoring so single-source floods that were mathematically unbannable on Gaming/Hosting/Performance/CDN now get banned in seconds.)</p><p>Repeat offenders get escalating bans automatically (the &quot;star system&quot;): each re-offense multiplies <code>ban_duration</code> per <code>star_duration_multiplicators</code> (<code>[1,2,4,8,16,32]</code>).</p><h2 id="connection-tracking-static-enable-connection-tracking-ct" tabindex="-1">Connection tracking (<code>static.enable_connection_tracking</code>, <code>ct_*</code>) <a class="header-anchor" href="#connection-tracking-static-enable-connection-tracking-ct" aria-label="Permalink to &quot;Connection tracking (`static.enable_connection_tracking`, `ct_*`)&quot;">​</a></h2><p>OpenShield watches TCP handshakes so it can tell &quot;real client&quot; from &quot;blind junk packets&quot;.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Plain meaning</th><th>When to touch it</th></tr></thead><tbody><tr><td><code>enable_connection_tracking</code></td><td><code>true</code></td><td>Drop blind SYN-ACK/RST packets (no prior SYN seen)</td><td>Turn off only on asymmetric routing</td></tr><tr><td><code>ct_syn_timeout_sec</code></td><td>300</td><td>How long a connection stays &quot;proven&quot; after its SYN</td><td>Keep ≥ your app&#39;s keepalive interval</td></tr><tr><td><code>ct_server_port_max</code></td><td>32768</td><td>Only connections to ports ≤ this are tracked</td><td>Keep default; <code>0</code> tracks all ports and breaks outbound traffic (apt, curl)</td></tr><tr><td><code>ct_established_exempt</code></td><td><code>true</code></td><td><strong>Sources with a proven TCP session are exempt from PPS/BPS/TCP scoring</strong></td><td>Leave on. This is the fix for &quot;I get banned uploading files&quot;</td></tr></tbody></table><p>The exemption is the important one. A source proves itself by sending a real data segment within <code>ct_syn_timeout_sec</code> of its SYN — something SFTP, backups, and every normal client do automatically, and spoofed floods can&#39;t. Exempt sources are still subject to SYN-rate, connection-rate, and UDP/ICMP scoring, and to the attack-mode caps. It works even if <code>enable_connection_tracking</code> is <code>false</code>.</p><h2 id="port-overrides-static-port-thresholds" tabindex="-1">Port overrides (<code>static.port_thresholds</code>) <a class="header-anchor" href="#port-overrides-static-port-thresholds" aria-label="Permalink to &quot;Port overrides (`static.port_thresholds`)&quot;">​</a></h2><p>For a port (or range) that legitimately exceeds your global limits — think backup agents, media streaming, a busy game port — you can give it its own limits. <strong>Max 8 entries.</strong> These replace the global PPS/BPS limits for traffic to those ports, in peacetime <em>and</em> during attack mode.</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  port_thresholds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;25565&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # single port</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      bps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">52428800</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # 50 MB/s</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">ports</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;8000-9000&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # a range</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      pps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      bps_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 0 = inherit the global value</span></span></code></pre></div><p><strong>When to touch:</strong> only when you see legit traffic to a specific port getting scored/banned and the established-connection exemption doesn&#39;t cover it (e.g. pure-UDP services).</p><h2 id="attack-mode-dynamic" tabindex="-1">Attack mode (<code>dynamic.*</code>) <a class="header-anchor" href="#attack-mode-dynamic" aria-label="Permalink to &quot;Attack mode (`dynamic.*`)&quot;">​</a></h2><p>Attack mode is declared when global traffic spikes far above your learned baseline (<code>spike_percentage</code>, default 200 = 3× baseline) for <code>attack_trigger_time</code> seconds (default 3), and clears after it settles.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Plain meaning</th><th>When to touch it</th></tr></thead><tbody><tr><td><code>attack_threshold_multiplier</code></td><td>0.5</td><td>During an attack, all per-IP thresholds are multiplied by this (0.5 = halved)</td><td>Raise toward 0.7–0.75 if legit users get banned mid-attack on busy nodes</td></tr><tr><td><code>attack_per_ip_pps</code></td><td>1000</td><td>Hard per-source PPS cap while an attack is active (0 = off)</td><td>Rarely — preset tunes it</td></tr><tr><td><code>attack_port_pps</code></td><td>10000</td><td><strong>Aggregate PPS cap per destination port during attacks</strong> (0 = off)</td><td>Set above your busiest legit port&#39;s normal rate</td></tr><tr><td><code>attack_min_pps</code> / <code>attack_min_bps</code></td><td>1000 / 1 MB/s</td><td>Absolute floors so a busy-but-normal server never enters attack mode</td><td>Raise if your normal load trips attack mode</td></tr><tr><td><code>attack_trigger_time</code></td><td>3</td><td>Consecutive spike seconds before attack mode declares</td><td>Rarely</td></tr><tr><td><code>attack_max_duration</code></td><td>300</td><td>Hard cap on attack-mode seconds (0 = no cap)</td><td>Rarely</td></tr><tr><td><code>new_source_limit</code></td><td>100</td><td>New unique IPs/s before new-source flood handling engages</td><td>Lower on small servers, raise on CDN-like nodes</td></tr><tr><td><code>new_source_ban_duration</code></td><td>30</td><td><strong>Each excess new source is temp-banned for this many seconds</strong></td><td>Raise (300–600) if rotation floods keep cycling back</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">v2.0 change: new sources get banned, not just dropped</p><p>Before v2.0, exceeding <code>new_source_limit</code> dropped a single packet per new source — useless against rotating floods. Now each excess new source is <strong>temp-banned</strong> for <code>new_source_ban_duration</code> seconds, so a rotating flood burns through its IP pool instead of walking through.</p></div><p>The per-port cap deserves emphasis: a spoofed flood can rotate source IPs but <strong>not the port it attacks</strong>. Capping the port&#39;s total rate throttles the flood no matter how many fake IPs it uses. Legit traffic on that port is throttled (not banned) until the attack clears.</p><h2 id="behavior-engine-behavior" tabindex="-1">Behavior engine (<code>behavior.*</code>) <a class="header-anchor" href="#behavior-engine-behavior" aria-label="Permalink to &quot;Behavior engine (`behavior.*`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Plain meaning</th><th>When to touch it</th></tr></thead><tbody><tr><td><code>behavior.enabled</code></td><td><code>true</code></td><td>Master switch: learns per-port baselines, flags lookalike bot clusters</td><td>Leave on</td></tr><tr><td><code>behavior.auto_block</code></td><td><code>true</code> (since v2.1.0)</td><td>Auto-ban cluster members for 1h at ≥85% confidence</td><td>Set <code>false</code> for report-only mode while you build trust</td></tr></tbody></table><p>Review clusters in the TUI behavior tab or with <code>sudo openshield behavior</code>. Note the engine <strong>freezes learning while an attack is declared</strong> — it mainly catches slow-burn botnets between floods. If you&#39;re planning a big legitimate traffic event (launch day), you can pre-emptively pause it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> suppress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auto-block</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 6h</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> schedule</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clear</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span></span></code></pre></div><h2 id="metrics-api-metrics" tabindex="-1">Metrics API (<code>metrics.*</code>) <a class="header-anchor" href="#metrics-api-metrics" aria-label="Permalink to &quot;Metrics API (`metrics.*`)&quot;">​</a></h2><p>Off by default. Serves everything the TUI shows as JSON for your own dashboards.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Plain meaning</th></tr></thead><tbody><tr><td><code>metrics.enabled</code></td><td><code>false</code></td><td>Turn the HTTP endpoint on</td></tr><tr><td><code>metrics.listen</code></td><td><code>127.0.0.1:9100</code></td><td>Bind address — keep localhost unless you need remote dashboards</td></tr><tr><td><code>metrics.api_key</code></td><td>random per install</td><td>Bearer token; manage with <code>openshield key</code> / <code>key set</code> / <code>key regen</code></td></tr><tr><td><code>metrics.rate_limit_per_sec</code></td><td>10</td><td>Requests/s per client IP (0 = unlimited)</td></tr><tr><td><code>metrics.whitelist</code></td><td><code>[]</code></td><td>IP/CIDR allowlist (empty = any IP with the key)</td></tr></tbody></table><p>Full guide: <a href="/pingless-studios-docs/openshield-xdp/user-guide/metrics-api">Metrics API</a>.</p><h2 id="alerts-alerter" tabindex="-1">Alerts (<code>alerter.*</code>) <a class="header-anchor" href="#alerts-alerter" aria-label="Permalink to &quot;Alerts (`alerter.*`)&quot;">​</a></h2><p>Discord/Slack webhook notifications for attacks, bans, and floods.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Plain meaning</th></tr></thead><tbody><tr><td><code>alerter.enabled</code></td><td><code>false</code></td><td>Turn alerts on</td></tr><tr><td><code>alerter.webhook_url</code></td><td><code>&quot;&quot;</code></td><td>Your Discord/Slack webhook URL</td></tr><tr><td><code>alerter.events</code></td><td><code>[]</code></td><td>Event types to send (empty = all)</td></tr><tr><td><code>alerter.graph_enabled</code></td><td><code>true</code></td><td>Attach a traffic graph to attack-end alerts</td></tr><tr><td><code>alerter.attack_updates</code></td><td><code>true</code></td><td>Progress embeds while an attack is ongoing</td></tr><tr><td><code>alerter.show_banned_ips</code></td><td><code>false</code></td><td>Include banned IPs inline in ban alerts</td></tr><tr><td><code>alerter.geo_breakdown</code></td><td><code>true</code></td><td>Continent/country split of banned IPs (needs GeoIP db)</td></tr></tbody></table><p>Test with <code>sudo openshield alert test</code>. Full format reference: <a href="/pingless-studios-docs/openshield-xdp/configuration/alerter">Alerter</a>.</p><h2 id="whitelist-blacklist-whitelist-cli" tabindex="-1">Whitelist &amp; blacklist (<code>whitelist.*</code>, CLI) <a class="header-anchor" href="#whitelist-blacklist-whitelist-cli" aria-label="Permalink to &quot;Whitelist &amp; blacklist (`whitelist.*`, CLI)&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">whitelist</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>\n<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  ips</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;203.0.113.10&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;198.51.100.0/24&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><p>Whitelisted IPs skip <strong>all</strong> mitigation — rate limits, validation, detection. Whitelist your office IP, monitoring, and upstream proxies. Manage live with the CLI; since v2.0 the commands <strong>persist to the YAML config</strong>, so entries survive loader restarts:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whitelist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 203.0.113.10</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # or: openshield wl add ...</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> whitelist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remove</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 203.0.113.10</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> openshield</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> blacklist</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5.6.7.8</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3600</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # manual ban, seconds</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Whitelisting is total</p><p>A whitelisted IP can flood you unchecked. Only whitelist infrastructure you control — never player/customer ranges.</p></div><h2 id="the-rest" tabindex="-1">The rest <a class="header-anchor" href="#the-rest" aria-label="Permalink to &quot;The rest&quot;">​</a></h2><p><code>validation.*</code> (malformed-packet filters), <code>maps.*</code> (BPF map sizes), <code>telemetry.*</code> (TUI polling), <code>pcap.*</code> (attack forensics capture), <code>geoip.*</code> (country blocking), <code>reports.*</code> (daily reports), and <code>license.*</code> are covered key-by-key in the <a href="/pingless-studios-docs/openshield-xdp/configuration/reference">full Configuration Reference</a>. The defaults are right for almost everyone.</p>',46)])])}const u=e(d,[["render",o]]);export{k as __pageData,u as default};
